170→export default function App() {
171→  const [tables, setTables] = useState<TableInfo[]>([]);
172→  const [loading, setLoading] = useState(true);
173→  const [error, setError] = useState<string | null>(null);
174→
175→  const refreshTables = useCallback(async () => {
176→    try {
177→      const response = await fetch('/api/tables');
178→      if (!response.ok) throw new Error('Failed to fetch tables');
179→      const data = await response.json();
180→      setTables(data);
181→    } catch (e) {
182→      console.error('Failed to refresh tables:', e);
183→    }
184→  }, []);
185→
186→  useEffect(() => {
187→    (async () => {
188→      try {
189→        const response = await fetch('/api/health');
190→        if (!response.ok) throw new Error('Backend is not available');
191→        await refreshTables();
192→      } catch (e) {
193→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
194→      } finally {
195→        setLoading(false);
196→      }
197→    })();
198→  }, [refreshTables]);
199→
200→  if (loading) {
201→    return <div className="app-loading">Connecting to backend...</div>;
202→  }
203→
204→  if (error) {
205→    return (
206→      <div className="app-error">Failed to connect: {error}</div>
207→    );
208→  }
209→
210→  return (
211→    <AgentProvider tables={tables} refreshTables={refreshTables}>
212→      <AppContent tables={tables} refreshTables={refreshTables} />
213→    </AgentProvider>
214→  );
215→}
